50→  changedFiles?: string[];
51→  diff?: string;
52→  checkpointFailure?: string;
53→  fetchFailure?: string;
54→} = {}): { respond: (request: SubprocessRequest) => SubprocessResult } {
55→  let createdSandboxName: string | undefined;
56→  return {
57→    respond(request) {
58→      if (request.command === 'git' && request.args.join(' ') === 'rev-parse --is-inside-work-tree') return result('true\n');
59→      if (request.command === 'git' && request.args.join(' ') === 'rev-parse HEAD') return result('base123\n');
60→      if (request.command === 'git' && request.args[0] === 'rev-parse') return result('checkpoint456\n');
61→      if (request.command === 'git' && request.args[0] === 'status') return result();
62→      if (request.command === 'git' && request.args[0] === 'fetch') {
63→        return options.fetchFailure ? result('', options.fetchFailure, 1) : result();
64→      }
65→      if (request.command === 'git' && request.args[0] === 'diff' && request.args.includes('--name-only')) {
66→        return result((options.changedFiles ?? []).map(filePath => `${filePath}\n`).join(''));
67→      }
68→      if (request.command === 'git' && request.args[0] === 'diff') return result(options.diff ?? '');
69→
70→      if (request.args.join(' ') === 'version') return result('Docker Sandbox 0.35.0\n');
71→      if (request.args.join(' ') === 'create --help') return result('Usage: sbx create --clone');
72→      if (request.args.join(' ') === 'ls --help') return result('Usage: sbx ls --json');
73→      if (request.args.join(' ') === 'policy init --help') return result('Usage: sbx policy init');
74→      if (request.args.join(' ') === 'policy ls --json') return result('[{"name":"local-policy"}]\n');
75→      if (request.args[0] === 'create') {
76→        createdSandboxName = request.args[request.args.indexOf('--name') + 1];
77→        return result();
78→      }
79→      if (request.command === 'sbx' && request.args[0] === 'rm') {
80→        createdSandboxName = undefined;
81→        return result();
82→      }
83→      if (request.args.join(' ') === 'ls --json') {
84→        return result(createdSandboxName
85→          ? JSON.stringify([{ id: `id-${createdSandboxName}`, name: createdSandboxName }])
86→          : '[]');
87→      }
88→
89→      const sandboxGitArgs = request.command === 'sbx' && request.args[0] === 'exec'
90→        ? request.args.slice(2)
91→        : [];
92→      if (sandboxGitArgs[0] === 'git' && sandboxGitArgs.includes('commit')) {
93→        if (options.checkpointFailure) return result('', options.checkpointFailure, 1);
94→        return result('[feature checkpoint456] checkpoint\n');
95→      }
