51→  diff?: string;
52→  checkpointFailure?: string;
53→  fetchFailure?: string;
54→} = {}): { respond: (request: SubprocessRequest) => SubprocessResult } {
55→  let createdSandboxName: string | undefined;
56→  return {
57→    respond(request) {
58→      if (request.command === 'git' && request.args.join(' ') === 'rev-parse --is-inside-work-tree') return result('true\n');
59→      if (request.command === 'git' && request.args.join(' ') === 'rev-parse HEAD') return result('base123\n');
60→      if (request.command === 'git' && request.args[0] === 'rev-parse') return result('checkpoint456\n');
61→      if (request.command === 'git' && request.args[0] === 'status') return result();
62→      if (request.command === 'git' && request.args[0] === 'fetch') {
63→        return options.fetchFailure ? result('', options.fetchFailure, 1) : result();
