 71→      if (request.args.join(' ') === 'create --help') return result('Usage: sbx create --clone');
 72→      if (request.args.join(' ') === 'ls --help') return result('Usage: sbx ls --json');
 73→      if (request.args.join(' ') === 'policy init --help') return result('Usage: sbx policy init');
 74→      if (request.args.join(' ') === 'policy ls --json') return result('[{"name":"local-policy"}]\n');
 75→      if (request.args[0] === 'create') {
 76→        createdSandboxName = request.args[request.args.indexOf('--name') + 1];
