 90→        ? request.args.slice(2)
 91→        : [];
 92→      if (sandboxGitArgs[0] === 'git' && sandboxGitArgs.includes('commit')) {
 93→        if (options.checkpointFailure) return result('', options.checkpointFailure, 1);
 94→        return result('[feature checkpoint456] checkpoint\n');
 95→      }
 96→      return result();
 97→    },
