101→function hostMutatingGitCalls(calls: SubprocessRequest[]): SubprocessRequest[] {
102→  const mutating = new Set(['checkout', 'switch', 'reset', 'merge', 'cherry-pick', 'rebase', 'apply', 'am']);
103→  return calls.filter(call => call.command === 'git' && mutating.has(call.args[0] ?? ''));
